TLM.f("Sancti/07-14",{"officium":"S. Bonaventuræ Episcopi Confessoris et Ecclesiæ Doctoris","rule":["vide C4a;","Gloria","CredoDA"],"ruleInherited":["Gloria"],"fallback":"Commune/C4a","from":{"Introitus":"Commune/C4a","Lectio":"Commune/C4a","GradualeP":"Commune/C4a","Tractus":"Commune/C4a","Evangelium":"Commune/C4a"},"sections":{"Introitus":[{"k":"ref","la":"Eccli 15:5"},{"k":"text","la":"In médio Ecclésiæ apéruit os ejus: et implévit eum Dóminus spíritu sapiéntiæ et intelléctus: stolam glóriæ índuit eum. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 91:2"},{"k":"text","la":"Bonum est confitéri Dómino: et psállere nómini tuo, Altíssime."},{"k":"macro","name":"Gloria"},{"k":"text","la":"In médio Ecclésiæ apéruit os ejus: et implévit eum Dóminus spíritu sapiéntiæ et intelléctus: stolam glóriæ índuit eum. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Deus, qui pópulo tuo aetérnae salútis beátum Bonaventúram minístrum tribuísti: praesta, quaésumus; ut, quem Doctórem vitae habúimus in terris, intercessórem habére mereámur in caelis."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Timótheum"},{"k":"ref","la":"2 Tim 4:1-8"},{"k":"text","la":"Caríssime: Testíficor coram Deo, et Jesu Christo, qui judicatúrus est vivos et mórtuos, per advéntum ipsíus et regnum ejus: prǽdica verbum, insta opportúne, importune: árgue, óbsecra, íncrepa in omni patiéntia, et doctrína. Erit enim tempus, cum sanam doctrínam non sustinébunt, sed ad sua desidéria, coacervábunt sibi magistros, pruriéntes áuribus, et a veritáte quidem audítum avértent, ad fábulas autem converténtur. Tu vero vígila, in ómnibus labóra, opus fac Evangelístæ, ministérium tuum ímple. Sóbrius esto. Ego enim jam delíbor, et tempus resolutiónis meæ instat. Bonum certámen certávi, cursum consummávi, fidem servávi. In réliquo repósita est mihi coróna justítiæ, quam reddet mihi Dóminus in illa die, justus judex: non solum autem mihi, sed et iis, qui díligunt advéntum ejus."}],"Graduale":[{"k":"ref","la":"Ps 36:30-31"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium."},{"k":"text","la":"Lex Dei ejus in corde ipsíus: et non supplantabúntur gressus ejus. Allelúja, allelúja.","mark":"V"},{"k":"ref","la":"Ps 109:4"},{"k":"text","la":"Jurávit Dóminus, et non pœnitébit eum: Tu es sacérdos in ætérnum, secúndum órdinem Melchísedech. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Eccli 45:9"},{"k":"text","la":"Amávit eum Dóminus, et ornávit eum: stolam glóriæ índuit eum."},{"k":"ref","la":"Osee 14:6"},{"k":"text","la":"Justus germinábit sicut lílium: et florébit in ætérnum ante Dóminum. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 36:30-31"},{"k":"text","la":"Os justi meditábitur sapiéntiam, et lingua ejus loquétur judícium."},{"k":"text","la":"Lex Dei ejus in corde ipsíus: et non supplantabúntur gressus ejus.","mark":"V"},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 5:13-19"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Vos estis sal terræ. Quod si sal evanúerit, in quo saliétur? Ad níhilum valet ultra, nisi ut mittátur foras, et conculcétur ab homínibus. Vos estis lux mundi. Non potest cívitas abscóndi supra montem pósita. Neque accéndunt lucérnam, et ponunt eam sub módio, sed super candelábrum, ut lúceat ómnibus, qui in domo sunt. Sic luceat lux vestra coram homínibus, ut vídeant ópera vestra bona, et gloríficent Patrem vestrum, qui in cœlis est. Nolíte putáre, quóniam veni sólvere legem aut prophétas: non veni sólvere, sed adimplére. Amen, quippe dico vobis, donec tránseat cœlum et terra, jota unum aut unus apex non præteríbit a lege, donec ómnia fiant. Qui ergo sólverit unum de mandátis istis mínimis, et docúerit sic hómines, mínimus vocábitur in regno cœlórum: qui autem fécerit et docúerit, hic magnus vocábitur in regno cœlórum."}],"Offertorium":[{"k":"ref","la":"Ps 88:25"},{"k":"text","la":"Véritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Sancti Bonaventúræ Confessóris tui atque Pontíficis, quǽsumus, Dómine, ánnua sollémnitas pietáti tuæ nos reddat accéptos: ut, per hæc piæ placatiónis offícia, et illum beáta retribútio comitétur, ei nobis grátiæ tuæ dona concíliet."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Luc 12:42"},{"k":"text","la":"Fidélis servus et prudens, quem constítuit dóminus super famíliam suam: ut det illis in témpore trítici mensúram. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Deus, fidélium remunerátor animárum: præsta; ut, beáti Bonaventúræ Confessóris tui atque Pontíficis, cujus venerándam celebrámus festivitátem, précibus indulgéntiam consequámur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"f17bbac22be741ea":{"t":"Sir 15, 5, Ps 91, 2\n(Sir 15, 5) Usred Crkve otvorio je Gospodin usta njegova i napunio ga duhom mudrosti i razuma, ogrnuo ga odjećom slave. (Ps. 91, 2) Dobro je slaviti Gospodina i pjevati imenu tvojem, Višnji!\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Sir 15, 5) Usred Crkve otvorio je Gospodin usta njegova i napunio ga duhom mudrosti i razuma, ogrnuo ga odjećom slave.","kn":"(Crkv. 15, 5). Usred Crkve otvorio je Gospodin njegova usta i napunio ga duhom mudrosti i razuma, ogrnuo ga odjećom slave (Aleluja, aleluja). (Ps. 91, 2.) Dobro je slaviti Gospodina i pjevati Imenu Tvomu,^ Višnji! Slava Ocu... Usred Crkve...","knRef":"Kniewald 1942, str. 812–813 (snimka 407) (OCR)"},"383b6102bfdbc765":{"t":"<i>Pomolimo se</i>.\nBože, koji si svome puku dao blaženoga Bonaventuru za vođu na putu vječnoga spasenja, daj molimo, da zavrijedimo da nam na nebesima bude zagovornik onaj koji nam je na zemlji bio naučitelj života.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si htio, da blaženi I. bude Tvomu puku vodič na putu spasa, podaj, molimo, da zavri jedimo imati za nebeskog zaštitnika onoga, koji nam je na zemlji bio učitelj života, po G. n.","knRef":"Kniewald 1942, str. 812–813 (snimka 407) (OCR)"},"c97d830457c280ab":{"t":"2 Tim 4, 1-8\nČitanje Poslanice bl. Pavla apostola Timoteju. Predragi, zaklinjem te pred Bogom i Isusom Kristom koji će suditi žive i mrtve njegovim dolaskom i njegovim kraljevstvom, propovijedaj riječ, revnuj u zgodno i nezgodno vrijeme, karaj, moli, opominji sa svom strpljivošću i naukom. Jer će doći vrijeme kad neće primati zdrave nauke, nego će oko sebe skupiti naučitelje po svojim požudama koji će im ugađati ušima. Odvraćat će uši od istine, a obraćat će ih k bajkama. Ali ti bdij, budi u svemu strpljiv, izvršuj djelo evanđeliste, ispunjavaj svoju službu. Budi trijezan! Ja sam već žrtvovan i vrlo je blizu vrijeme moje smrti. Dobar sam boj bio, tijek svršio, vjeru održao. Na kraju mi je pripravljen vijenac pravde koji će mi u onaj dan dati Gospodin, pravedni sudac, ali ne samo meni, nego i onima koji ljube njegov dolazak.","kn":"Čitanje poslanice bi. Pavla apostola Timoteju (II, 4, 1-8). Predragi! Zaklinjem te pred Bogom i Isusom Kristom, koji će suditi žive i mrtve, njegovim dolaskom 1 njegovim kraljevstvom: Propovijedaj riječ, revnuj u zgodno i nezgodno vrijeme, karaj, moli, opominji sa svom strpljivošću i naukom. Jer će doći vrijeme, kad ne će primati zdrave nauke, nego će oko sebe skupiti učitelje po svojim požudama, kakio ugađa ušima. Odvraćat će uši od istine, a obraćat će se k bajkama. Ali ti bdij, budi u svemu strpljiv, izvršuj djelo kao evanđelist, ispunjavaj svoju službu. Budi trijezan! Jer ja se već žrtvujem i vrlo je blizu vrijeme moje smrti. Vojevao sam dobar boj, dovršio trku, sačuvao vjeru. Na kraju pripravljen mi je vijenac pravde, koji će mi u onaj dan dati Gospodin, pravedan sudac; ali ne samo meni, nego i onima, koji ljube njegov dolazak.","knRef":"Kniewald 1942, str. 470–471 (snimka 236) (OCR)"},"1a8220d6482ca957":{"t":"Ps 36, 30-31\nPravednikova usta raspravljaju o mudrosti i njegov jezik govori o pravdi. Zakon mu je Božji u srcu, i noge mu neće posrnuti.\n\nPs 109, 4\n<i>Aleluja</i>, <i>aleluja</i>.\nZakleo se Gospodin i neće se pokajati: ti si svećenik dovijeka po redu Melkisedekovu. <i>Aleluja</i>.","kn":"(Ps. 36, 30-31). Pravednikova usta govore mudrost i njegov jezik kazuje pravdu. Zakon je Božji u njegovu srcu i njegove noge ne ce posrnuti.\n\nAleluja, aleluja (Ps, 109, 4). Zakle se Gospodin i ne će se pokajati: Ti si svećenik dovijeka, po redu Melkisedekovu, aleluja.","knRef":"Kniewald 1942, str. 540–541 (snimka 271) (OCR)"},"a220bcd1476c8c48":{"t":"Mt 5, 13-19\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme reče Isus svojim učenicima: Vi ste sol zemlje. Ako sol izvjetri, čim će se soliti? Za ništa više ne vrijedi, nego da se izbaci i da je ljudi pogaze. Vi ste svjetlo svijeta. Ne može se sakriti grad sazidan na gori. Niti se upaljuje svijeća i postavlja pod varićak, nego na svijećnjak da svijetli svima koji su u kući. Tako neka svijetli vaše svjetlo pred ljudima da vide vaša dobra djela i slave vašega nebeskog Oca. Nemojte misliti da sam došao ukinuti zakon ili proroke! Nisam došao ukinuti nego dopuniti. Zaista vam kažem, dok stoji nebo i zemlja, neće od zakona nestati ni jednog slova, niti jednog znaka, dok se sve ne ispuni. Tko, dakle, dokine jednu od ovih najmanjih zapovijedi i tako nauči ljude, bit će najmanji u kraljevstvu nebeskom. A tko bude vršio i naučavao, taj će biti velik u kraljevstvu nebeskom.","kn":"t Slijedi sveto evanđelje po Mateju (5, 13-19). U ono vrijeme reče Isus svojim učenicima: Vi ste sol ze^ji. Ako se sol pokvari, čim će se soliti? Nije više ni zašto, nego da se baci van, da je pogaze ljudi. Vi ste svijetlo svijetu. Ne može se sakriti na gori sazidan grad. Niti se upaljuje svijetlo i po- stavlja pod posudu, nego na svijećnjak, da svijetli svima u kući. Tako neka svijetli vaše svijetlo pred ljudima, da vide vaša dobra djela i slave vašega nebeskog Oca. Nemojte misliti, da sam došao ukinuti zakon ili proroke! Nijesam došao ukinuti, nego dopuniti. Zaista vam kažem, dok ne prođe nebo i zemlja, ne će od zakona nestati ni jednoga slova ni jednoga znaka, dok se ne ispuni sve. Tko, 'dakle, dokine jednu od ovUi najmanjih zapovijedi i tako nauči ljude, bit će najmanji u kraljevstvu nebeskom, a tko bude vršio i naučavao, taj će biti velik u kraljevstvu nebeskom.","knRef":"Kniewald 1942, str. 524–525 (snimka 263) (OCR)"},"88bea9a296c140ac":{"t":"Ps 88, 25\nMoja će vjernost i moje milosrđe biti s njime, i svojim ću imenom uzdići njegovu moć.","kn":"(Ps. 88, 25). Istina je moja i milosrđe moje B njime i u ime će se moje uzdići moć njegova.","knRef":"Kniewald 1942, str. 452–453 (snimka 227) (OCR)"},"f4a80468b1707d75":{"t":"Neka nas godišnja svetkovina svetoga Bonaventure tvoga priznavaoca i biskupa učini, molimo, Gospodine, dragima tvojoj očinskoj dobroti da po ovoj pobožnoj pomirbenoj službi njega prati blažena nagrada i nama udijeli tvoje milosne darove.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, neka nas godišnja svetkovina svetoga I., priznavaoca Tvoga, omili dobroti Tvojoj, da ova pobožna zadovoljština umnoži njegovu nagradu i nama pribavi darove Tvoje milosti, po G. n.","knRef":"Kniewald 1942, str. 812–813 (snimka 407) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Predslovlje. Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti, Oče svemogući, vjećni Bože, po Kristu, Gospodinu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i . blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se i naši glasovi združe s njihovima, smjernim ispovijedanjem govoreći:","knRef":"Kniewald 1942, str. 758–759 (snimka 380) (OCR)"},"43352d99b4b928c1":{"t":"Lk 12, 42\nEvo vjernog i razboritog sluge koga je postavio Gospodin nad svojom obitelji, da im na vrijeme daje za hranu pšenicu koja im pripada.","kn":"(Lk. 12, 42). Evo razboritog i vjernog upravitelja, koga postavi Gospodin nad družinom svojom, da im na vrijeme daje hranu, koja im pripada.","knRef":"Kniewald 1942, str. 524–525 (snimka 263) (OCR)"},"59fc3b05b914f158":{"t":"<i>Pomolimo se</i>.\nBože, koji nagrađuješ duše vjernih daj da postignemo oproštenje po molitvama blaženog Bonaventure tvoga priznavaoca i biskupa kojega časnu svetkovinu slavimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji nagrađuješ vjerne duše, podaj, molimo, da zagovorom blaženog Bonaventure, priznavaoca Tvoga i biskupa, kojega časnu svetkovinu slavimio, dostignemo oprošten je, ipo G. n.","knRef":"Kniewald 1942, str. 638–639 (snimka 320) (OCR)"}},"variants":{"paschal":{"Introitus":[{"k":"ref","la":"Eccli 15:5"},{"k":"text","la":"In médio Ecclésiæ apéruit os ejus: et implévit eum Dóminus spíritu sapiéntiæ et intelléctus: stolam glóriæ índuit eum. Allelúja, allelúja."},{"k":"ref","la":"Ps 91:2"},{"k":"text","la":"Bonum est confitéri Dómino: et psállere nómini tuo, Altíssime."},{"k":"macro","name":"Gloria"},{"k":"text","la":"In médio Ecclésiæ apéruit os ejus: et implévit eum Dóminus spíritu sapiéntiæ et intelléctus: stolam glóriæ índuit eum. Allelúja, allelúja."}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Timotheum"},{"k":"ref","la":"2 Tim 4:1-8"},{"k":"text","la":"Caríssime: Testíficor coram Deo, et Jesu Christo, qui judicatúrus est vivos et mórtuos, per advéntum ipsíus et regnum ejus: prǽdica verbum, insta opportúne, importune: árgue, óbsecra, íncrepa in omni patiéntia, et doctrína. Erit enim tempus, cum sanam doctrínam non sustinébunt, sed ad sua desidéria, coacervábunt sibi magistros, pruriéntes áuribus, et a veritáte quidem audítum avértent, ad fábulas autem converténtur. Tu vero vígila, in ómnibus labóra, opus fac Evangelístæ, ministérium tuum ímple. Sóbrius esto. Ego enim jam delíbor, et tempus resolutiónis meæ instat. Bonum certámen certávi, cursum consummávi, fidem servávi. In réliquo repósita est mihi coróna justítiæ, quam reddet mihi Dóminus in illa die, justus judex: non solum autem mihi, sed et iis, qui díligunt advéntum ejus."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 5:13-19"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Vos estis sal terræ. Quod si sal evanúerit, in quo saliétur? Ad níhilum valet ultra, nisi ut mittátur foras, et conculcétur ab homínibus. Vos estis lux mundi. Non potest cívitas abscóndi supra montem pósita. Neque accéndunt lucérnam, et ponunt eam sub módio, sed super candelábrum, ut lúceat ómnibus qui in domo sunt. Sic lúceat lux vestra coram homínibus, ut vídeant ópera vestra bona, et gloríficent Patrem vestrum, qui in cœlis est. Nolíte putáre, quóniam veni sólvere legem aut prophétas: non veni sólvere, sed adimplére. Amen, quippe dico vobis, donec tránseat cœlum et terra, jota unum aut unus apex non præteríbit a lege, donec ómnia fiant. Qui ergo sólverit unum de mandátis istis mínimis, et docúerit sic hómines, mínimus vocábitur in regno cœlórum: qui autem fécerit et docúerit, hic magnus vocábitur in regno cœlórum."}]}}});
